    text: 'The \'one-time pad\' encryption method, later proven mathematically unbreakable when used correctly by Claude Shannon in 1949, was originally patented in 1919 based on the work of which AT&T engineer?',
    text_tr: 'Doğru kullanıldığında matematiksel olarak kırılamaz olduğu daha sonra 1949\'da Claude Shannon tarafından kanıtlanan \'tek kullanımlık şerit\' (one-time pad) şifreleme yöntemi, 1919\'da hangi AT&T mühendisinin çalışmasına dayanılarak patentlenmiştir?',
    options: { A: 'Gilbert Vernam', B: 'Claude Shannon', C: 'Alan Turing', D: 'Marian Rejewski', E: 'Joseph Mauborgne' },
    options_tr: { A: 'Gilbert Vernam', B: 'Claude Shannon', C: 'Alan Turing', D: 'Marian Rejewski', E: 'Joseph Mauborgne' },
    answer: 'A',
    difficulty: 3,
    explanation: 'Gilbert Vernam, an AT&T Bell Labs engineer, patented the Vernam cipher in 1919; Joseph Mauborgne later suggested using truly random, non-repeating keys, creating the modern one-time pad.',
