    text: 'Which ancient Chinese mathematical text, compiled over centuries and finalized around the 1st century AD, contains early methods for solving systems of linear equations using a matrix-like array of counting rods?',
    text_tr: 'Yüzyıllar boyunca derlenip MS 1. yüzyıl civarında son halini alan ve sayma çubuklarından oluşan matris benzeri bir dizilimle doğrusal denklem sistemlerini çözmek için erken yöntemler içeren antik Çin matematik metni hangisidir?',
    options: { A: 'The Book of Changes', B: 'The Nine Chapters on the Mathematical Art', C: 'The Zhoubi Suanjing', D: 'The Sun Zi Suanjing', E: 'The Huainanzi' },
    options_tr: { A: 'Değişimler Kitabı (İ Ching)', B: 'Matematik Sanatı Üzerine Dokuz Bölüm (Jiuzhang Suanshu)', C: 'Zhoubi Suanjing', D: 'Sun Zi Suanjing', E: 'Huainanzi' },
    answer: 'B',
