    id: 'mat_444',
    text: 'Working independently of, and around the same time as, Newton and Leibniz in the West, which 17th-century Japanese mathematician developed early ideas equivalent to determinants and made major contributions to the native Japanese mathematical tradition known as \'wasan\'?',
    text_tr: 'Batı\'da Newton ve Leibniz ile yaklaşık aynı dönemde, onlardan bağımsız olarak çalışan ve determinanta eşdeğer erken fikirler geliştiren, ayrıca \'wasan\' olarak bilinen yerli Japon matematik geleneğine büyük katkılar sağlayan 17. yüzyıl Japon matematikçi kimdir?',
