    text: 'Chebyshev\'s inequality, a fundamental result in probability theory that applies to any distribution regardless of its shape, guarantees that no more than 1/k² of a distribution\'s values can lie more than k standard deviations from what?',
    text_tr: 'Herhangi bir dağılıma, şeklinden bağımsız olarak uygulanabilen ve olasılık teorisinin temel sonuçlarından biri olan Çebişev eşitsizliği, bir dağılımın değerlerinin en fazla 1/k²\'sinin, ortalamadan k standart sapmadan daha fazla uzakta olabileceğini garanti eder. Burada sözü edilen \'ortalama\' nedir?',
