    text: 'Hermann Weyl\'s equidistribution theorem, published in 1916, describes the statistically uniform distribution of the fractional parts of integer multiples of which kind of number?',
    text_tr: 'Hermann Weyl\'in 1916\'da yayımlanan eş dağılım (equidistribution) teoremi, hangi tür bir sayının tam sayı katlarının ondalık kısımlarının istatistiksel olarak düzgün dağıldığını tanımlar?',
    options: { A: 'A prime number', B: 'An irrational number', C: 'A perfect square', D: 'A rational number', E: 'An even integer' },
    options_tr: { A: 'Bir asal sayı', B: 'İrrasyonel bir sayı', C: 'Bir tam kare', D: 'Rasyonel bir sayı', E: 'Bir çift sayı' },
    answer: 'B',
    difficulty: 3,
    explanation: 'Weyl\'s equidistribution theorem shows that the fractional parts of n times an irrational number, as n ranges over the positive integers, are equidistributed across the interval from 0 to 1.',
