    options_tr: { A: 'Yaklaşık on yılda bir', B: 'Yaklaşık her gün', C: 'Yaklaşık ayda bir', D: 'Yaklaşık yılda bir', E: 'Yaklaşık haftada bir' },
    answer: 'C',
    difficulty: 2,
    explanation: 'Littlewood\'s Law states that, given the huge number of events an average person experiences (roughly 1,000 per day), a one-in-a-million \'miracle\' should be expected to occur about once a month purely by chance.',
