    text_tr: 'Birçok kişi tarafından ilk bilgisayar programcısı olarak kabul edilen, Charles Babbage\'ın önerdiği Analitik Motor üzerine, bir makine tarafından yürütülmesi amaçlanan ilk algoritma sayılan notlar da dahil olmak üzere kapsamlı notlar yazan 19. yüzyıl matematikçisi kimdir?',
