    text_tr: '1747\'de titreşen bir tel üzerine yaptığı çalışmada tek boyutlu dalga denklemini ilk formüle eden ve çözen Fransız matematikçi ve fizikçi kimdir?',
    options: { A: 'Jean le Rond d\'Alembert', B: 'Joseph-Louis Lagrange', C: 'Pierre-Simon Laplace', D: 'Leonhard Euler', E: 'Daniel Bernoulli' },
