    text_tr: '1970\'lerde Roger Penrose tarafından geliştirilen Penrose döşemesi, bir düzlemi küçük bir şekil kümesiyle, asla tekrar etmeyen bir düzende kaplar; buna rağmen periyodik döşemelerde normalde yasak olan bir dönme simetrisi sergiler. Bu simetri hangisidir?',
    options: { A: 'Üçgen (3 kat) simetri', B: 'Dört kat simetri', C: 'Altı kat simetri', D: 'Sekiz kat simetri', E: 'Beş kat simetri' },
