    text_tr: 'Topolojide bir yüzeyin \'cinsi (genus)\', gayriresmi olarak, sahip olduğu hangi özelliğin sayısıdır? Sıradan bir kürenin cinsi 0, simit şeklindeki bir torusun cinsi ise 1\'dir.',
    options: { A: 'Vertices', B: 'Handles (holes)', C: 'Faces', D: 'Edges', E: 'Boundary components' },
