    options_tr: { A: 'Alt halka', B: 'Yan küme (koset)', C: 'Homomorfizma', D: 'İdeal', E: 'Bölüm cismi' },
    answer: 'D',
    difficulty: 2,
    explanation: 'Ideals generalize the notion of \'multiples\' in ordinary integers and are used to construct quotient rings.',
