    text_tr: '17. yüzyıl Fransız matematikçisi ve mimarı Girard Desargues, perspektif çiziminde kullanılan kaçış noktaları gibi izdüşüm altında korunan özellikleri inceleyen hangi geometri dalının kurucularından biri sayılır?',
