    text: 'In 1872, Karl Weierstrass startled the mathematical community by presenting a function that is continuous at every single point yet has what unusual property everywhere else?',
    text_tr: '1872\'de Karl Weierstrass, matematik dünyasını, her noktada sürekli olduğu halde başka her yerde hangi alışılmadık özelliğe sahip olan bir fonksiyon sunarak şaşırtmıştır?',
