    options_tr: { A: 'Her aralıkta sınırsızdır', B: 'Değerlerini sonsuz kez tekrarlar', C: 'Hiçbir noktada türevlenebilir değildir', D: 'Yalnızca rasyonel değerler alır', E: 'Her rasyonel sayıda süreksizdir' },
    answer: 'C',
    difficulty: 3,
    explanation: 'The Weierstrass function is continuous everywhere but differentiable nowhere, contradicting the earlier intuition that continuous functions must be smooth almost everywhere.',
