    text: 'In abstract algebra, a commutative ring in which every nonzero element has a multiplicative inverse is called what structure, the natural setting for ordinary arithmetic with rational, real, or complex numbers?',
    text_tr: 'Soyut cebirde, sıfırdan farklı her elemanının bir çarpımsal tersi bulunan değişmeli bir halkaya, rasyonel, gerçek veya karmaşık sayılarla yapılan sıradan aritmetiğin doğal ortamı olan hangi yapı denir?',
